"""Generated by solo-to-scale; edit `templates/tools/tests/test_portfolio.py` in the plugin, then run upgrade.

The portfolio: each venture's summary carries counts and short lists but never its business documents; the
overview reads the newest summary from each repo, lists a venture it can't read with the reason, keeps hostile
text as text, and deploys only behind a Cloudflare Access login.
"""
from __future__ import annotations

import io
import json
import subprocess
import sys
import zipfile
from pathlib import Path

import pytest

TOOLS = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(TOOLS))
sys.path.insert(0, str(Path(__file__).resolve().parent))
import approval  # noqa: E402
import build_dashboard as bd  # noqa: E402
import build_portfolio as bp  # noqa: E402
import tickets  # noqa: E402
from test_dashboard import EVIL, NOW, app, data_of, fake, guard, root  # noqa: E402,F401
from test_tickets import REPO  # noqa: E402

OTHER = "acme/second-venture"


def zipped(summary: dict | bytes, name: str = "summary.json") -> bytes:
    buf = io.BytesIO()
    with zipfile.ZipFile(buf, "w") as z:
        z.writestr(name, summary if isinstance(summary, bytes) else json.dumps(summary))
    return buf.getvalue()


def venture_summary(**extra) -> dict:
    return {"schema": bd.SUMMARY_SCHEMA, "project": {"name": "Second Venture", "one_line": EVIL, "repo": OTHER},
            "built": "2026-11-23T11:17:00Z", "month": "2026-11", "stage": {"number": 9}, "slices": {"done": 1, "total": 4},
            "github": {"ok": True, "approvals_waiting": [{"number": 3, "title": EVIL, "url": "javascript:alert(1)"}],
                       "tickets": {"open": 2}, "costs": {"total": 5.0, "cap": 40.0, "roles": []}, "activity": [], "merged": []},
            **extra}


def portfolio(root: Path, ventures: list, **extra) -> None:
    (root / "founder/portfolio.json").write_text(json.dumps({"ventures": ventures, **extra}), encoding="utf-8")


@pytest.fixture()
def hub(monkeypatch: pytest.MonkeyPatch) -> dict:
    """A fake `gh api` for other repos: path -> bytes, or an exception to raise."""
    replies: dict = {}
    seen: list = []

    def gh_bytes(path: str) -> bytes:
        seen.append(path)
        got = replies.get(path)
        if got is None or isinstance(got, Exception):
            raise got or subprocess.CalledProcessError(1, "gh")
        return got
    monkeypatch.setattr(bp, "gh_bytes", gh_bytes)
    replies["seen"] = seen
    return replies


def artifacts(repo: str, *arts: dict) -> tuple[str, bytes]:
    return f"repos/{repo}/actions/artifacts?name={bp.ARTIFACT}&per_page=10", json.dumps({"artifacts": list(arts)}).encode()


def test_the_summary_carries_no_business_documents(root, fake, tmp_path):
    out = tmp_path / "data" / "summary.json"
    assert bd.main(["build", "--root", str(root), "--out", str(tmp_path / "site"), "--summary", str(out)]) == 0
    text = out.read_text(encoding="utf-8")
    summary = json.loads(text)
    assert summary["schema"] == bd.SUMMARY_SCHEMA and summary["project"]["name"] == "Example Startup"
    assert "We sell invoices" not in text and "Margin of safety" not in text, "documents and memos stay in the repo"
    assert summary["slices"] == {"total": 1, "done": 1, "building": []}
    assert [d["id"] for d in summary["decisions_waiting"]] == ["B-01"]
    assert summary["github"]["ok"] and summary["github"]["tickets"] == {"open": 0, "claimed": 0, "blocked": 0}


def test_the_overview_reads_each_venture_and_lists_the_ones_it_cant(root, fake, hub, monkeypatch):
    path, body = artifacts(OTHER, {"id": 11, "created_at": "2026-11-22T10:00:00Z"},
                           {"id": 12, "created_at": "2026-11-23T11:20:00Z"}, {"id": 13, "created_at": "2026-11-23T12:00:00Z", "expired": True})
    hub[path] = body
    hub[f"repos/{OTHER}/actions/artifacts/12/zip"] = zipped(venture_summary())
    hub.update(dict([artifacts("acme/not-upgraded")]))
    portfolio(root, [{"repo": OTHER, "dashboard": "https://pm.second.example"}, "acme/not-upgraded", "acme/secret",
                     "not a repo; rm -rf /", {"repo": OTHER}], stale_hours=3)

    data = bp.build(root, now=NOW)
    rows = {v["repo"]: v for v in data["ventures"]}
    assert list(rows) == [REPO, OTHER, "acme/not-upgraded", "acme/secret", "not a repo; rm -rf /"], "duplicates dropped"
    here = rows[REPO]
    assert here["here"] and here["ok"] and here["summary"]["project"]["name"] == "Example Startup" and not here["stale"]
    second = rows[OTHER]
    assert second["ok"] and second["summary"]["slices"]["total"] == 4, "the newest unexpired summary"
    assert second["age_hours"] == 0.7 and not second["stale"] and second["dashboard"] == "https://pm.second.example"
    assert "upgrade the venture" in rows["acme/not-upgraded"]["why"]
    assert "PORTFOLIO_TOKEN" in rows["acme/secret"]["why"]
    assert rows["not a repo; rm -rf /"]["why"] == "not a repo name like owner/name"
    assert not any("rm -rf" in p for p in hub["seen"]), "a malformed name is never sent to gh"

    page = bp.page(data)
    assert page.count("</script>") == 2 and "<img src=x" not in page and bp.MARKER in page
    assert data_of(page)["ventures"][1]["summary"]["project"]["one_line"] == EVIL


def test_a_bad_or_old_summary_is_flagged_not_trusted(root, fake, hub):
    portfolio(root, [OTHER], include_this_repo=False)
    path, body = artifacts(OTHER, {"id": 5, "created_at": "2026-11-20T00:00:00Z"})
    hub[path] = body
    for blob, why in [(zipped({"schema": 99}), "ValueError"), (zipped(venture_summary(), "other.json"), "KeyError"),
                      (b"not a zip", "BadZipFile"), (b"x" * (bp.MAX_ZIP + 1), "ValueError")]:
        hub[f"repos/{OTHER}/actions/artifacts/5/zip"] = blob
        [row] = bp.build(root, now=NOW)["ventures"]
        assert not row["ok"] and why in row["why"]
    hub[f"repos/{OTHER}/actions/artifacts/5/zip"] = zipped(venture_summary(built="2026-11-20T00:00:00Z"))
    [row] = bp.build(root, now=NOW)["ventures"]
    assert row["ok"] and row["stale"] and row["age_hours"] == 84.0


def test_the_token_is_portfolio_token_when_set(monkeypatch):
    calls = []

    def run(cmd, **kw):
        calls.append(kw["env"].get("GH_TOKEN"))
        return subprocess.CompletedProcess(cmd, 0, b"{}")
    monkeypatch.setattr(bp.subprocess, "run", run)
    monkeypatch.setenv("GH_TOKEN", "repo-token")
    monkeypatch.delenv("PORTFOLIO_TOKEN", raising=False)
    bp.gh_bytes("x")
    monkeypatch.setenv("PORTFOLIO_TOKEN", "portfolio-token")
    bp.gh_bytes("x")
    assert calls == ["repo-token", "portfolio-token"]


def test_no_ventures_means_no_portfolio(root, tmp_path, capsys):
    out = tmp_path / "gh-out"
    assert bp.main(["enabled", "--root", str(root), "--github-output", str(out)]) == 0
    assert out.read_text(encoding="utf-8") == "enabled=no\n"
    portfolio(root, [OTHER])
    assert bp.main(["enabled", "--root", str(root), "--github-output", str(out)]) == 0
    assert out.read_text(encoding="utf-8").endswith("enabled=yes\n")


def test_hosting_is_behind_a_login_like_the_dashboard(root, monkeypatch, tmp_path):
    portfolio(root, [OTHER], host="portfolio.example.com", cloudflare_pages_project="example-portfolio")

    def run_guard(apps):
        monkeypatch.setenv("CLOUDFLARE_API_TOKEN", "t")
        monkeypatch.setenv("CLOUDFLARE_ACCOUNT_ID", "0123456789abcdef0123456789abcdef")
        monkeypatch.setattr(bd, "http", lambda url, headers=None: (200, {}, json.dumps(
            {"success": True, "result": apps, "result_info": {"total_pages": 1}})))
        out = tmp_path / "gh-out"
        out.write_text("", encoding="utf-8")
        return bp.main(["guard", "--root", str(root), "--github-output", str(out)]), out.read_text(encoding="utf-8")
    assert run_guard([app("portfolio.example.com")]) == (1, "deploy=no\nproject=\n"), "pages.dev left open"
    assert run_guard([app("portfolio.example.com", "example-portfolio.pages.dev")]) == (0, "deploy=yes\nproject=example-portfolio\n")
    replies = {"https://portfolio.example.com/": (200, {}, f"<meta {bp.MARKER} content=\"1\">"),
               "https://example-portfolio.pages.dev/": (302, {}, "")}
    monkeypatch.setattr(bd, "http", lambda url, headers=None: replies[url])
    assert bp.main(["verify", "--root", str(root)]) == 1
    replies["https://portfolio.example.com/"] = (302, {"Location": "https://acme.cloudflareaccess.com/"}, "")
    assert bp.main(["verify", "--root", str(root)]) == 0


# --- sorting, filters and approve actions (in the browser, no server) ------------------------------------

@pytest.mark.parametrize("module", [bd, bp])
def test_tables_sort_and_filter_and_approvals_open_github_only(module):
    page = module.PAGE.read_text(encoding="utf-8")
    assert "aria-sort" in page and "opts.filters" in page and 'type: "search"' in page, "tables sort and filter"
    assert 'function actions(a)' in page and '"/approve"' in page and '"/reject "' in page
    assert r'/^https:\/\/github\.com\/[^\s#]+$/i' in page, "approve buttons only for github.com links"
    assert "#new_comment_field" in page


@pytest.mark.parametrize("module", [bd, bp])
def test_the_pages_never_build_html_from_strings(module):
    page = module.PAGE.read_text(encoding="utf-8")
    for sink in ("innerHTML", "outerHTML", "insertAdjacentHTML", "document.write", "eval(", "new Function"):
        assert sink not in page, sink
